reference_solution:
def canCompleteCircuit(gas, cost):
    if sum(gas) < sum(cost):
        return -1
    start = tank = 0
    for i in range(len(gas)):
        tank += gas[i] - cost[i]
        if tank < 0:
            start = i + 1
            tank = 0
    return start

brute_force_solution:
def canCompleteCircuit(gas, cost):
    n = len(gas)
    for s in range(n):
        tank = 0
        good = True
        for j in range(n):
            i = (s + j) % n
            tank += gas[i] - cost[i]
            if tank < 0:
                good = False
                break
        if good:
            return s
    return -1

